// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;

    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(uint256 amount, uint256 warpTime) public {
        amount = bound(amount, 1 ether, 2 ether);
        warpTime = bound(warpTime, 1, 365 days);

        // attacker deposits 2 ether with unlockTime 0, becoming the counterparty of Collect
        Attacker attacker = new Attacker{value: 2 ether}(c);

        // make Collect's time condition hold and let the attacker trigger Collect
        vm.warp(warpTime);
        attacker.reap(amount);

        // During the ongoing Collect (lock held), the re-entrant Put in the attacker's
        // receive() must have FAILED. The mutant releases the lock before the body,
        // so the re-entrant Put succeeds.
        assertTrue(attacker.reentrantPutFailed());
    }
}

contract Attacker {
    X_WALLET public c;
    bool public reentrantPutFailed = true;
    bool private entered;

    constructor(X_WALLET _c) payable {
        c = _c;
        c.Put{value: msg.value}(0);
    }

    function reap(uint256 am) external {
        c.Collect(am);
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            try c.Put(0) { reentrantPutFailed = false; } catch { reentrantPutFailed = true; }
        }
    }
}
